select q.title, q.time_limit_minutes, (select count(*) from public.quiz_questions x where x.quiz_id = q.id) as items, (select sum(n.marks) from public.quiz_questions x join public.questions n on n.id = x.question_id where x.quiz_id = q.id) as marks, (select count(*) from public.quiz_classes c where c.quiz_id = q.id) as classes from public.quizzes q where q.id in ('a995cb80-3962-54c9-91dc-3641e1177f13') order by q.title;
